class Memory:
    """The agent's durable memory: markdown files under memories/ in the thread's drive."""

    def __init__(self, t: Any) -> None:
        self._t = t

    def search(self, query: str) -> Any:
        """Recall by query (the drive's content index over memories/)."""
        a = _prune({"q": query})
        return self._t.call("memory_search", a)

    def remember(self, **opts: Any) -> Any:
        """Write a memory file."""
        a = {}
        a.update(_camel_keys(opts))
        return self._t.call("memory_remember", a)

    def forget(self, path: str) -> Any:
        """Delete a memory file by its path."""
        a = _prune({"path": path})
        return self._t.call("memory_forget", a)


class Tasks:
    """Open work mounted to a thread: the thread's agent is prompted with it until it is done (runs/thread-<id>/mounts.tsx)."""

    def __init__(self, t: Any) -> None:
        self._t = t

    def mount(self, *, task: Optional[str] = None, folder: Optional[str] = None, project: Optional[str] = None, assignee: Optional[str] = None, labels: Optional[List[Any]] = None, status: Optional[List[Any]] = None, label: Optional[str] = None, thread_id: Optional[str] = None) -> Any:
        """Mount a task, a task list (a folder or a query) or a project to this thread: the agent is prompted with its open work until it is done.

        Keyword arguments:
            task: A task id, or the address or path of a .task.tsx.
            folder: A folder (a path in your Drive, or an absolute address cloud://home/<uuid>/…): the tasks at or under it.
            project: A project id, or the address or path of a .project.tsx.
            assignee: A query: whose tasks ("me", "user:<id>" or "agent:<id>").
            labels: A query: tasks with these labels.
            status: A query: tasks with these statuses.
            label: The mount's name in the thread. Omitted: made from what it mounts.
            thread_id: The thread to mount it to. Omitted: the thread this code runs in.
        """
        a = {}
        a.update(_prune({"task": task, "folder": folder, "project": project, "assignee": assignee, "labels": labels, "status": status, "label": label, "threadId": thread_id}))
        a = self._t._with_thread(a)
        return self._t.call("mount_tasks", a)

    def unmount(self, label: str, thread_id: Optional[str] = None) -> Any:
        """Remove a mount from this thread by its label."""
        a = _prune({"label": label, "threadId": thread_id})
        a = self._t._with_thread(a)
        return self._t.call("unmount_tasks", a)

    def mounts(self, thread_id: Optional[str] = None) -> Any:
        """This thread's mounts, the open tasks they hold and whether the loop still prompts the agent."""
        a = _prune({"threadId": thread_id})
        a = self._t._with_thread(a)
        return self._t.call("list_mounts", a)


